mapper.select:
SELECT 
FROM public.nocode_record_history
WHERE deleted = 0 AND application_id = CAST(#{app} AS bigint)
AND object_id = CAST(#{object} AS bigint) AND record_id = #{record}
AND source_json ->> 'taskContributionId' = #{contribution}
ORDER BY id

SELECT 
FROM public.nocode_record_history
WHERE deleted = 0 AND application_id = CAST(#{app} AS bigint)
AND object_id = CAST(#{object} AS bigint) AND record_id = #{record}
AND after_json ->> 'revision' = #{revision}
ORDER BY id LIMIT 2

SELECT jsonb_build_object('id', id::text, 'recordId', record_id, 'operation', operation, 'time', occurred_at, 'actor', creator, 'before', before_json, 'after', after_json, 'source', CASE WHEN jsonb_exists(source_json, 'relatedEvents') THEN(source_json - 'relatedEvents') || jsonb_build_object('relatedUpdate', true) ELSE source_json END
, 'fields',( SELECT coalesce(jsonb_agg(jsonb_build_object('id', f ->> 'id', 'name', f ->> 'name')), '[]'::jsonb) FROM jsonb_array_elements(definition_json -> 'fields') f), 'detailFields',( SELECT coalesce(jsonb_agg(jsonb_build_object('id', d ->> 'id', 'name', d ->> 'name', 'fields',( SELECT coalesce(jsonb_agg(jsonb_build_object('id', f ->> 'id', 'name', f ->> 'name')), '[]'::jsonb) FROM jsonb_array_elements(d -> 'fields') f))), '[]'::jsonb) FROM jsonb_array_elements(definition_json -> 'details') d)
)::text FROM public.nocode_record_history WHERE object_id = CAST(#{object} AS bigint) AND deleted = 0 AND occurred_at <= CAST(#{end} AS timestamptz) AND pg_visible_in_snapshot(written_txid, CAST(#{visibility} AS pg_snapshot)) AND occurred_at >= CAST(#{start} AS timestamptz) AND operation <> 'BASELINE' AND (occurred_at, id) >(CAST(#{cursorTime} AS timestamptz), #{cursorId})
AND record_id IN #{record}
ORDER BY occurred_at, id LIMIT 1000

SELECT jsonb_build_object('recordId', record_id, 'row', after_json, 'fields',( SELECT coalesce(jsonb_agg(jsonb_build_object('id', f ->> 'id', 'name', f ->> 'name')), '[]'::jsonb) FROM jsonb_array_elements(definition_json -> 'fields') f))::text FROM ( SELECT DISTINCT ON (record_id) record_id, after_json, definition_json FROM public.nocode_record_history WHERE object_id = CAST(#{object} AS bigint) AND deleted = 0 AND occurred_at <= CAST(#{end} AS timestamptz) AND pg_visible_in_snapshot(written_txid, CAST(#{visibility} AS pg_snapshot))
AND record_id IN #{record}
ORDER BY record_id, occurred_at DESC, id DESC) s
